### 1. Modelo de Dados e Lógica de Negócio (PatchedDownloader.cs)

Este arquivo contém a inteligência artificial do download, leitura do script Lua, verificação de hash e gestão de erros.

```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Net.Http;
using System.Net.Http.Headers;
using System.Net.NetworkInformation;
using System.Net.Security;
using System.Threading.Tasks;
using System.Linq;

namespace MyProject.Models
{
    public class UpdateFile
    {
        public string FileName { get; set; }
        public string IntegrityHash { get; set; }
        public long FileSize { get; set; } // Tamanho esperado
        public int Status { get; set; } // 0=Não iniciada, 1=Baixando, 2=Concluída, 3=Falha, 4=Cachado
        public long BytesReceived { get; set; } // Progresso atual

        public bool Exists { get; private set; }

        // Metadados persistentes para recuperação (Simulação simples de persistência)
        public static string CacheFilePath => Path.Combine(Path.GetDirectoryName(Application.ExecutablePath), "download_state.json");

        // Classe para serializar o estado ao fechar a janela/app
        public static void SaveState(string filename, long progressPercent)
        {
            var stateData = new Dictionary<string, object>
            {
                ["FileName"] = filename,
                ["ProgressPercent"] = progressPercent
            };
            File.WriteAllText(CacheFilePath, System.Text.Json.JsonSerializer.Serialize(stateData));
        }

        public static LoadStateResult LoadState(string filename)
        {
            return null; // Simplificação: Neste exemplo básico, vamos confiar na reescrita da pasta ou ler json
        }
    }

    public class PatchDownloader
    {
        private HttpClient _httpClient;
        private readonly List<UpdateFile> _filesToProcess;

        // Estado global da aplicação
        public string ServerConnectionMsg { get; private set; }
        public string AuthMsg { get; private set; }
        public string PrepareMsg { get; private set; }
        public string ErrorLogMsg { get; private set; }
        public string NextActionMsg { get; private set; } // Mensagem personalizada por etapa

        // Configurações
        public const string SERVER_URL = "https://hil-speed.hetzner.com";
        public const string LOCAL_PATCH_FOLDER = "patch";

        public PatchDownloader()
        {
            _httpClient = new HttpClient();
            _httpClient.DefaultRequestHeaders.Authorization = new System.Net.HttpCredential(null, null);

            // Parse dos arquivos
            var luaContent = @"
                updates = {
                    { Version = 1, FileName = ""100MB.bin"", Integrity= ""741sa871sa5871sa"" }, 
                    { Version = 2, FileName = ""1GB.bin"", Integrity= ""741sa871sa5871sa"" }, 
                    { Version = 3, FileName = ""10GB.bin"", Integrity= ""741sa871sa5871sa"" }, 
                    { Version = 4, FileName = ""test.rgz"", Integrity= ""741sa871sa5871sa"" }
                }";
            // Na prática real você carrega o arquivo .txt do servidor e descodifica aqui

            // Converter String Lua simulada para Lista
            var matches = Regex.Matches(luaContent, @"\{.*?"FileName"\s*=\s*"([^"]+)"", "\s*Integrity=[^\"\"]*([a-z0-9]+)"");

            foreach(var m in matches) {
                UpdateFile f = new UpdateFile();
                f.FileName = m.Groups[1].Value;
                f.IntegrityHash = m.Groups[2].Value;
                f.FileSize = GetFileSizeFromFileName(f.FileName); // Tentativa heurística ou via API header
                _filesToProcess.Add(f);
            }
        }

        public async Task<bool> InitializeAsync()
        {
            Console.WriteLine("Conectando ao servidor...");
            ServerConnectionMsg = "Conectando ao servidor...";
            await Task.Delay(1000); 

            // Simulação de conexão
            var testResponse = await _httpClient.GetAsync($"{SERVER_URL}/api/status");
            if(testResponse.StatusCode == System.Net.HttpStatusCode.OK)
            {
                ServerConnectionMsg = "Conectado com sucesso.";
                return true;
            } else {
                ServerConnectionMsg = "Erro: Acesso denegado (Access denied) ou Servidor indisponível.";
                return false;
            }
        }

        private void TryAutenticate()
        {
            AuthMsg = "Autenticando no servidor...";
            // Adicione lógica de Auth token aqui
            Thread.Sleep(500);
        }

        private void TryPrepare()
        {
            PrepareMsg = "Preparando para iniciar o download...";
            Thread.Sleep(500);
        }

        public async Task ProcessFileList()
        {
            foreach(var file in _filesToProcess)
            {
                // 1. Verificar existência e Hash
                CheckExistingFiles(file);

                if (file.Exists && VerifyHash(file))
                {
                    NextActionMsg = $"O arquivo já existe. Não há necessidade de fazer download (Hash idêntico).";
                    continue; 
                }

                // 2. Tenta baixar
                await AttemptDownload(file);
            }
        }

        private void CheckExistingFiles(UpdateFile file)
        {
            var path = Path.Combine(GetAppDir(), LOCAL_PATCH_FOLDER, file.FileName);
            if(File.Exists(path))
            {
                file.Exists = true;
                Console.WriteLine($"Arquivo encontrado na pasta: {file.FileName}");
            } else {
                file.Exists = false;
            }
        }

        private bool VerifyHash(UpdateFile file)
        {
            var path = Path.Combine(GetAppDir(), LOCAL_PATCH_FOLDER, file.FileName);
            if(!File.Exists(path)) return false;

            var actualHash = CalculateMD5(filePath: path);
            return actualHash.Equals(file.IntegrityHash, StringComparison.OrdinalIgnoreCase);
        }

        private async Task AttemptDownload(UpdateFile file)
        {
            NextActionMsg = "Reiniciando o download.."; // Caso seja re-tentativa

            var url = $"{SERVER_URL}/{file.FileName}";
            var filePath = Path.Combine(GetAppDir(), LOCAL_PATCH_FOLDER, file.FileName);

            // Criação da pasta se não existir
            Directory.CreateDirectory(Path.GetDirectoryName(filePath));

            // Inicializa fluxo de stream
            using (var response = await _httpClient.GetAsync(url))
            {
                response.EnsureSuccessStatusCode();

                // Stream para gravar no disco
                using (var fs = new FileStream(filePath, FileMode.Create, FileAccess.Write))
                {
                    using (var reader = new StreamReader(response.Content.ReadAsStreamAsync().Result))
                        await reader.CopyToAsync(fs, bufferSize: 4096);

                    file.BytesReceived = file.FileSize;
                    file.Status = 2;
                }
            }
        }

        private string GetAppDir()
        {
            // Retorna a pasta do exe
            return Path.GetDirectoryName(Application.ExecutablePath);
        }

        public static string CalculateMD5(string filePath)
        {
            using (var fs = new FileStream(filePath, FileMode.Open, FileAccess.Read))
            using (var sha256Hasher = SHA256.Create())
            {
                byte[] data = sha256Hasher.ComputeHash(fs);
                return Convert.ToBase64String(data);
            }
        }

        // Função auxiliar para simular o parser do arquivo Lua
        private static long GetFileSizeFromFileName(string fileName) 
        {
            return 10 * 1024 * 1024; // Fictício para exemplo
        }
    }
}
